import{_ as e}from"./chunks/popup-translate.CYMtVXLB.js";import{_ as o}from"./chunks/page-selection.ClIk5vyj.js";import{_ as a}from"./chunks/page-dock.BwiiXitq.js";import{_ as r,o as s,c as l,a2 as d}from"./chunks/framework.CfwCq2QB.js";const A=JSON.parse('{"title":"快速上手（5 分钟）","description":"","frontmatter":{},"headers":[],"relativePath":"guide/quick-start.md","filePath":"guide/quick-start.md"}'),i={name:"guide/quick-start.md"};function c(n,t,h,p,m,g){return s(),l("div",null,[...t[0]||(t[0]=[d('<h1 id="快速上手-5-分钟" tabindex="-1">快速上手（5 分钟） <a class="header-anchor" href="#快速上手-5-分钟" aria-label="Permalink to &quot;快速上手（5 分钟）&quot;">​</a></h1><p>装好 DevGo 后，先做这三件事，最核心的能力就都用上了。</p><h2 id="_1-整页双语翻译" tabindex="-1">1. 整页双语翻译 <a class="header-anchor" href="#_1-整页双语翻译" aria-label="Permalink to &quot;1. 整页双语翻译&quot;">​</a></h2><p><strong>作用</strong>：把整个网页翻译成你的语言，译文插在原文段落后面，边读边对照。</p><p><strong>怎么做</strong>：打开任意外文网页，任选其一——</p><ul><li>点工具栏 DevGo 图标 →「翻译」页 → 点「翻译当前页面」</li><li>在页面空白处右键 →「翻译当前页面（再次点击恢复原文）」</li><li>在 <code>chrome://extensions/shortcuts</code> 给「整页行间翻译」绑定快捷键后一键切换</li></ul><p>译文随滚动按需加载，长页面不用等全页翻完；再点一次「显示原文」即恢复。</p><img src="'+e+'" alt="弹窗翻译页"><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>引擎默认是微软翻译（免翻墙），也可切换 Google 或自己的 AI 大模型，见<a href="/dev-go-docs/features/page-translate.html">整页双语翻译</a>。</p></div><h2 id="_2-划词翻译与-ai-动作" tabindex="-1">2. 划词翻译与 AI 动作 <a class="header-anchor" href="#_2-划词翻译与-ai-动作" aria-label="Permalink to &quot;2. 划词翻译与 AI 动作&quot;">​</a></h2><p><strong>作用</strong>：选中一段文字，上方浮出工具条，不用跳转页面。</p><p><strong>怎么做</strong>：在网页里选中文字——</p><ul><li>网页文字：<strong>翻译 / 解释 / 总结 / 问 AI</strong>，选中单个英文单词还会并行显示词典释义</li><li>输入框里的文字：<strong>润色 / 纠错 / 正式</strong>，AI 处理完可一键「替换原文」</li><li>工具条动作不够用？在设置页「划词 → 工具条动作」添加自己的动作（如「转 JSON」「解释报错」），填名称和提示词即可</li></ul><img src="'+o+'" alt="划词工具条"><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>解释、总结等 AI 动作需要先配置模型，见 <a href="/dev-go-docs/settings/models.html">AI 模型</a>。觉得工具条碍事？弹窗「功能」页可只对当前网站停用。</p></div><h2 id="_3-悬浮快捷栏" tabindex="-1">3. 悬浮快捷栏 <a class="header-anchor" href="#_3-悬浮快捷栏" aria-label="Permalink to &quot;3. 悬浮快捷栏&quot;">​</a></h2><p><strong>作用</strong>：网页右侧贴边的深色悬浮条，悬停展开常用操作。</p><p><strong>怎么做</strong>：把鼠标移到网页右侧边缘——</p><ul><li><strong>翻译本页 / 显示原文</strong>：一键切换整页翻译</li><li><strong>AI 总结本页</strong>：打开侧边栏并自动开始总结</li><li><strong>AI 助手</strong>：打开侧边栏对话</li><li><strong>回到顶部</strong>：页面滚过一段距离后才出现</li></ul><p>悬浮条可以上下拖动；点左上角 × 可以选择「本次不显示 / 在本站不显示 / 全部网站都不显示」。</p><img src="'+a+'" alt="悬浮快捷栏"><h2 id="默认快捷键" tabindex="-1">默认快捷键 <a class="header-anchor" href="#默认快捷键" aria-label="Permalink to &quot;默认快捷键&quot;">​</a></h2><table tabindex="0"><thead><tr><th>快捷键</th><th>作用</th></tr></thead><tbody><tr><td><code>Alt+1</code>（macOS <code>⌥1</code>）</td><td>打开弹窗（默认页）</td></tr><tr><td><code>Alt+2</code>（macOS <code>⌥2</code>）</td><td>打开 / 关闭侧边栏 AI 助手</td></tr><tr><td><code>Alt+3</code>（macOS <code>⌥3</code>）</td><td>打开弹窗「网络」页</td></tr><tr><td><code>Alt+4</code>（macOS <code>⌥4</code>）</td><td>打开弹窗「资源」页</td></tr><tr><td>未绑定</td><td>整页行间翻译（可在 <code>chrome://extensions/shortcuts</code> 绑定）</td></tr></tbody></table><p>所有快捷键都可以自定义，见<a href="/dev-go-docs/settings/general.html#快捷键">通用与外观</a>。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>配置 <a href="/dev-go-docs/settings/models.html">AI 模型</a>，解锁 AI 解释、总结、润色与侧边栏助手</li><li>开着代理上网？看看<a href="/dev-go-docs/features/ip-protection.html">真实 IP 防护</a></li><li>想让 AI 直接操作网页？了解 <a href="/dev-go-docs/features/webmcp.html">网页工具（WebMCP）</a></li></ul>',26)])])}const I=r(i,[["render",c]]);export{A as __pageData,I as default};
